const clean = value =>
  String(value ?? '').trim();

const upper = value =>
  clean(value).toUpperCase();

const rows = $input
  .all()
  .map(item => item.json ?? {})
  .filter(
    row => clean(row.opportunity_key)
  );


function normalizeDomain(value) {
  let domain =
    clean(value).toLowerCase();

  if (!domain) {
    return '';
  }

  return domain
    .replace(/^https?:\/\//, '')
    .split('/')[0]
    .split('?')[0]
    .split('#')[0]
    .replace(/^www\./, '')
    .replace(/\.$/, '');
}


function normalizeEmail(value) {
  return clean(value).toLowerCase();
}


function normalizeLinkedIn(value) {
  return clean(value)
    .toLowerCase()
    .split('?')[0]
    .split('#')[0]
    .replace(/\/+$/, '');
}


function normalizeCompanyName(value) {
  return clean(value)
    .toLowerCase()
    .replace(/\s+/g, ' ');
}


function sharesCampaignIdentity(
  first,
  second,
) {
  const firstDomain =
    normalizeDomain(
      first.company_domain
    );

  const secondDomain =
    normalizeDomain(
      second.company_domain
    );

  if (
    firstDomain &&
    secondDomain &&
    firstDomain === secondDomain
  ) {
    return true;
  }


  const firstEmail =
    normalizeEmail(
      first.contact_email
    );

  const secondEmail =
    normalizeEmail(
      second.contact_email
    );

  if (
    firstEmail &&
    secondEmail &&
    firstEmail === secondEmail
  ) {
    return true;
  }


  const firstLinkedIn =
    normalizeLinkedIn(
      first.contact_linkedin_url
    );

  const secondLinkedIn =
    normalizeLinkedIn(
      second.contact_linkedin_url
    );

  if (
    firstLinkedIn &&
    secondLinkedIn &&
    firstLinkedIn === secondLinkedIn
  ) {
    return true;
  }


  if (
    !firstDomain &&
    !secondDomain
  ) {
    const firstCompany =
      normalizeCompanyName(
        first.company_name
      );

    const secondCompany =
      normalizeCompanyName(
        second.company_name
      );

    if (
      firstCompany &&
      secondCompany &&
      firstCompany === secondCompany
    ) {
      return true;
    }
  }

  return false;
}


function campaignRank(row) {
  const outreachStatus =
    upper(row.outreach_status);

  const researchStatus =
    upper(
      row.contact_research_status
    );

  const approvalStatus =
    upper(row.outreach_approval);

  const sentAt =
    clean(row.sent_at);


  if (
    sentAt ||
    [
      'SENT',
      'REPLIED',
      'FOLLOW_UP_DUE',
    ].includes(outreachStatus)
  ) {
    return 500;
  }


  if (
    approvalStatus === 'APPROVED' ||
    outreachStatus === 'APPROVED'
  ) {
    return 400;
  }


  if (
    outreachStatus === 'DRAFT_READY'
  ) {
    return 300;
  }


  if (
    researchStatus === 'COMPLETED'
  ) {
    return 200;
  }


  if (
    researchStatus === 'IN_PROGRESS'
  ) {
    return 100;
  }


  return 0;
}


function isCanonicalCampaign(row) {
  const rowKey =
    clean(row.opportunity_key);

  const relatedCampaigns =
    rows
      .filter(candidate =>
        sharesCampaignIdentity(
          row,
          candidate,
        ) &&
        campaignRank(candidate) > 0
      )
      .sort(
        (first, second) => {
          const rankDifference =
            campaignRank(second) -
            campaignRank(first);

          if (rankDifference) {
            return rankDifference;
          }

          const sentDifference =
            clean(second.sent_at)
              .localeCompare(
                clean(first.sent_at)
              );

          if (sentDifference) {
            return sentDifference;
          }

          return clean(
            first.opportunity_key
          ).localeCompare(
            clean(
              second.opportunity_key
            )
          );
        },
      );

  const canonicalKey =
    clean(
      relatedCampaigns[0]
        ?.opportunity_key
    );

  return (
    !canonicalKey ||
    canonicalKey === rowKey
  );
}


const today =
  new Date()
    .toISOString()
    .slice(0, 10);

const dueCampaigns = [];


for (const row of rows) {
  const opportunityKey =
    clean(row.opportunity_key);

  const outreachStatus =
    upper(row.outreach_status);

  const responseStatus =
    upper(row.response_status) ||
    'NO_RESPONSE';

  const followUpStatus =
    upper(row.follow_up_status) ||
    'NOT_STARTED';

  const followUpDate =
    clean(row.follow_up_date)
      .slice(0, 10);

  const sentAt =
    clean(row.sent_at);

  const gmailThreadId =
    clean(row.gmail_thread_id);

  const replyDetectedAt =
    clean(row.reply_detected_at);

  const followUpSentAt =
    clean(row.follow_up_sent_at);


  if (
    opportunityKey.startsWith('test::')
  ) {
    continue;
  }

  if (outreachStatus !== 'SENT') {
    continue;
  }

  if (
    responseStatus !== 'NO_RESPONSE' ||
    replyDetectedAt
  ) {
    continue;
  }

  if (
    !sentAt ||
    !gmailThreadId ||
    !followUpDate
  ) {
    continue;
  }

  if (followUpDate > today) {
    continue;
  }

  if (
    followUpSentAt ||
    followUpStatus === 'SENT'
  ) {
    continue;
  }

  if (
    ![
      'NOT_STARTED',
      'FAILED',
    ].includes(followUpStatus)
  ) {
    continue;
  }

  if (!isCanonicalCampaign(row)) {
    continue;
  }


  const daysOverdue =
    Math.max(
      0,
      Math.floor(
        (
          new Date(
            `${today}T00:00:00Z`
          ).getTime() -
          new Date(
            `${followUpDate}T00:00:00Z`
          ).getTime()
        ) /
        (
          24 *
          60 *
          60 *
          1000
        )
      )
    );


  dueCampaigns.push({
    ...row,

    follow_up_ready:
      true,

    follow_up_status:
      'NOT_STARTED',

    follow_up_approval:
      'PENDING',

    follow_up_date:
      followUpDate,

    days_overdue:
      daysOverdue,

    selection_checked_at:
      new Date().toISOString(),
  });
}


dueCampaigns.sort(
  (first, second) =>
    clean(first.follow_up_date)
      .localeCompare(
        clean(second.follow_up_date)
      )
);


if (!dueCampaigns.length) {
  return [
    {
      json: {
        follow_up_ready:
          false,

        due_count:
          0,

        checked_date:
          today,

        message:
          'No follow-up campaigns are currently due.',

        selection_checked_at:
          new Date().toISOString(),
      },
    },
  ];
}


return dueCampaigns.map(
  campaign => ({
    json: {
      ...campaign,

      due_count:
        dueCampaigns.length,

      checked_date:
        today,

      message:
        'Campaign is ready for follow-up draft generation.',
    },
  })
);

const clean = value =>
  String(value ?? '').trim();

const upper = value =>
  clean(value).toUpperCase();

const items = $input
  .all()
  .map(item => item.json ?? {});


const savedDrafts =
  items.filter(item =>
    upper(item.follow_up_status) ===
      'DRAFT_READY' &&
    clean(item.follow_up_draft)
  );


const failedDrafts =
  items.filter(item =>
    upper(item.follow_up_status) ===
      'FAILED'
  );


if (savedDrafts.length) {
  return [
    {
      json: {
        success: true,

        follow_up_result:
          'DRAFTS_SAVED',

        saved_count:
          savedDrafts.length,

        opportunity_keys:
          savedDrafts.map(item =>
            clean(
              item.opportunity_key
            )
          ),

        message:
          savedDrafts.length === 1
            ? (
                '1 follow-up draft generated ' +
                'and saved for approval.'
              )
            : (
                `${savedDrafts.length} follow-up ` +
                'drafts generated and saved ' +
                'for approval.'
              ),

        checked_at:
          new Date().toISOString(),
      },
    },
  ];
}


if (failedDrafts.length) {
  return [
    {
      json: {
        success: false,

        follow_up_result:
          'DRAFT_VALIDATION_FAILED',

        failed_count:
          failedDrafts.length,

        failures:
          failedDrafts.map(item => ({
            opportunity_key:
              clean(
                item.opportunity_key
              ),

            reasons:
              Array.isArray(
                item
                  .follow_up_draft_validation_reasons
              )
                ? item
                    .follow_up_draft_validation_reasons
                : [],
          })),

        message:
          'One or more generated follow-up ' +
          'drafts failed validation.',

        checked_at:
          new Date().toISOString(),
      },
    },
  ];
}


const first =
  items[0] ?? {};


return [
  {
    json: {
      success: true,

      follow_up_result:
        'NO_DUE_CAMPAIGNS',

      due_count:
        0,

      message:
        clean(first.message) ||
        'No follow-up campaigns are currently due.',

      checked_at:
        new Date().toISOString(),
    },
  },
];

const source =
  $json ?? {};

const clean = value =>
  String(value ?? '').trim();

const upper = value =>
  clean(value).toUpperCase();


function parseOutput(value) {
  if (
    value &&
    typeof value === 'object'
  ) {
    if (
      value.output &&
      typeof value.output === 'object'
    ) {
      return value.output;
    }

    return value;
  }

  const text =
    clean(value)
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/, '');

  if (!text) {
    return {};
  }

  try {
    return JSON.parse(text);
  } catch {
    return {
      follow_up_draft: text,
    };
  }
}


const parsed =
  parseOutput(
    source.output ??
    source.text ??
    source.response ??
    {}
  );


let followUpDraft =
  clean(
    parsed.follow_up_draft ??
    parsed.email_draft ??
    parsed.text
  );


/*
 * A threaded Gmail reply does not need a new
 * subject. Remove one if the model added it.
 */
followUpDraft =
  followUpDraft
    .replace(
      /^subject:\s*[^\r\n]+(?:\r?\n)+/i,
      ''
    )
    .trim();


const validationReasons = [];

const words =
  followUpDraft
    .split(/\s+/)
    .filter(Boolean);


const opportunityKey =
  clean(
    source.opportunity_key
  );

const applicationStatus =
  upper(
    source.application_status
  );

const outreachMode =
  upper(
    source.outreach_mode
  );


if (!opportunityKey) {
  validationReasons.push(
    'The generated draft could not be linked to an opportunity.'
  );
}


if (!followUpDraft) {
  validationReasons.push(
    'The generated follow-up draft is empty.'
  );
}


if (
  followUpDraft &&
  words.length < 50
) {
  validationReasons.push(
    `The follow-up is too short: ${words.length} words.`
  );
}


if (words.length > 120) {
  validationReasons.push(
    `The follow-up is too long: ${words.length} words.`
  );
}


if (
  /\{\{.*?\}\}|<[^<>]+>|\[(?:name|company|position|date|email)[^\]]*\]/i
    .test(followUpDraft)
) {
  validationReasons.push(
    'The follow-up contains an unresolved placeholder.'
  );
}


const falseApplicationClaim =
  /\b(?:i\s+(?:have\s+)?applied|my application|following up on my application)\b/i
    .test(followUpDraft);


if (
  applicationStatus !== 'APPLIED' &&
  [
    'ADJACENT_ROLE',
    'SPECULATIVE',
  ].includes(outreachMode) &&
  falseApplicationClaim
) {
  validationReasons.push(
    'The draft falsely claims that an application was submitted.'
  );
}


if (
  !/best regards,\s*yahya menkari/i
    .test(followUpDraft)
) {
  validationReasons.push(
    'The required sign-off is missing.'
  );
}


const now =
  new Date().toISOString();

const draftValid =
  validationReasons.length === 0;


return {
  json: {
    ...source,

    follow_up_draft:
      followUpDraft,

    follow_up_status:
      draftValid
        ? 'DRAFT_READY'
        : 'FAILED',

    follow_up_approval:
      'PENDING',

    follow_up_generated_at:
      now,

    follow_up_draft_valid:
      draftValid,

    follow_up_draft_word_count:
      words.length,

    follow_up_draft_validation_reasons:
      validationReasons,

    last_updated:
      now,
  },
};
